  completed_steps INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  idempotency_key TEXT UNIQUE,
  available_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS worker_heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  beat_at INTEGER NOT NULL
);
`;

/**
 * Opens the SQLite database shared by the server and worker processes, and makes sure the schema
 * exists so that either process can start first.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
  transaction(db, () => db.exec(SCHEMA));
  return db;
}

/** Runs `fn` inside a BEGIN IMMEDIATE transaction, rolling back if it throws. Keep `fn` synchronous and short. */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // No transaction is open (for example, COMMIT already failed and rolled back).
    }
    throw err;
  }
  return result;
}

const statements = new WeakMap<DatabaseSync, Map<string, StatementSync>>();

function stmt(db: DatabaseSync, sql: string): StatementSync {
  let cache = statements.get(db);
  if (!cache) {
    cache = new Map();
    statements.set(db, cache);
  }
  let s = cache.get(sql);
  if (!s) {
    s = db.prepare(sql);
    cache.set(sql, s);
  }
  return s;
}

function one(db: DatabaseSync, sql: string, ...params: Param[]): JobRow | undefined {
  return stmt(db, sql).get(...params) as unknown as JobRow | undefined;
}

function many(db: DatabaseSync, sql: string, ...params: Param[]): JobRow[] {
  return stmt(db, sql).all(...params) as unknown as JobRow[];
}

function exec(db: DatabaseSync, sql: string, ...params: Param[]): void {
  stmt(db, sql).run(...params);
}

export interface NewJobRow {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | null;
  now: string;
}

export function insertJob(db: DatabaseSync, job: NewJobRow): void {
  exec(
    db,
    `INSERT INTO jobs (id, input, steps, fail_attempts, status, attempts, completed_steps, output, error,
                       idempotency_key, available_at, created_at, updated_at)
     VALUES (?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    job.id,
    job.input,
    job.steps,
    job.failAttempts,
    job.idempotencyKey,
    job.now,
    job.now,
  );
}

export function getJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

export function getJobByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
}

/** Lists jobs newest first. */
export function listJobs(db: DatabaseSync): JobRow[] {
  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

/** Returns the job left in `running` by an interrupted attempt, if any. */
export function findRunningJob(db: DatabaseSync): JobRow | undefined {
  return one(db, "SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1");
}

/** Clears progress for an attempt that is being replayed from step zero. */
export function resetAttemptProgress(db: DatabaseSync, id: string, now: string): void {
  exec(db, "UPDATE jobs SET completed_steps = 0, updated_at = ? WHERE id = ? AND status = 'running'", now, id);
}

/** Atomically moves the oldest eligible queued job to running and counts the new attempt. */
export function claimNextJob(db: DatabaseSync, nowMs: number, now: string): JobRow | undefined {
  return one(
    db,
    `UPDATE jobs
        SET status = 'running', attempts = attempts + 1, completed_steps = 0,
            output = NULL, error = NULL, updated_at = ?
      WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ?
                   ORDER BY seq LIMIT 1)
      RETURNING *`,
    now,
    nowMs,
  );
}

export function setProgress(db: DatabaseSync, id: string, completed: number, now: string): void {
  exec(db, "UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'", completed, now, id);
}

export function completeJob(db: DatabaseSync, id: string, steps: number, output: string, now: string): void {
  exec(
    db,
    `UPDATE jobs SET status = 'completed', completed_steps = ?, output = ?, error = NULL, updated_at = ?
      WHERE id = ? AND status = 'running'`,
    steps,
    output,
    now,
    id,
  );
}

export function requeueJob(db: DatabaseSync, id: string, availableAtMs: number, now: string): void {
  exec(
    db,
    `UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL,
            available_at = ?, updated_at = ?
      WHERE id = ? AND status = 'running'`,
    availableAtMs,
    now,
    id,
  );
}

export function failJob(db: DatabaseSync, id: string, error: string, now: string): void {
  exec(
    db,
    `UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = ?, updated_at = ?
      WHERE id = ? AND status = 'running'`,
    error,
    now,
    id,
  );
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  exec(
    db,
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at',
    nowMs,
  );
}

export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = stmt(db, 'SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return row?.beat_at;
}

export function clearHeartbeat(db: DatabaseSync): void {
  exec(db, 'DELETE FROM worker_heartbeat WHERE id = 1');
}

