import type { JobRow } from './db.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job representation returned by every endpoint that returns a job. */
export interface JobView {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface NewJobPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export type ParseResult =
  | { ok: true; payload: NewJobPayload; idempotencyKey: string | undefined }
  | { ok: false; fields: FieldError[] };

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** Serializes a stored job into the public shape. Internal columns are omitted. */
export function toJobView(row: JobRow): JobView {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed_steps, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** True when a stored job was created from exactly this (defaults-applied) payload. */
export function samePayload(row: JobRow, payload: NewJobPayload): boolean {
  return row.input === payload.input && row.steps === payload.steps && row.fail_attempts === payload.failAttempts;
}

function isJsonMediaType(value: string): boolean {
  return value.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/**
 * Validates a job submission. Collects every detectable problem rather than stopping at the first.
 *
 * @param contentTypeValues all Content-Type header values received
 * @param idempotencyKeyValues all Idempotency-Key header values received
 * @param body the raw request body, or null if it exceeded the size limit
 */
export function parseCreateRequest(
  contentTypeValues: readonly string[],
  idempotencyKeyValues: readonly string[],
  body: Buffer | null,
): ParseResult {
  const fields: FieldError[] = [];

  let idempotencyKey: string | undefined;
  if (idempotencyKeyValues.length > 1) {
    fields.push({ field: 'Idempotency-Key', message: 'must be sent only once' });
  } else if (idempotencyKeyValues.length === 1) {
    const key = idempotencyKeyValues[0]!;
    if (IDEMPOTENCY_KEY_PATTERN.test(key)) idempotencyKey = key;
    else fields.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 letters, digits, underscores or hyphens' });
  }

  const fail = (): ParseResult => ({ ok: false, fields });

  if (contentTypeValues.length !== 1 || !isJsonMediaType(contentTypeValues[0]!)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
    return fail();
  }
  if (body === null) {
    fields.push({ field: 'body', message: 'request body is too large' });
    return fail();
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(body.toString('utf8'));
  } catch {
    fields.push({ field: 'body', message: 'body must be valid JSON' });
    return fail();
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.push({ field: 'body', message: 'body must be a JSON object' });
    return fail();
  }

  const obj = parsed as Record<string, unknown>;
  const has = (name: string) => Object.hasOwn(obj, name);

  for (const name of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(name)) fields.push({ field: name, message: 'is not a recognised field' });
  }

  let input = '';
  if (!has('input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (obj.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = obj.input;
  }

  const intField = (name: 'steps' | 'failAttempts', min: number, max: number, fallback: number): number => {
    if (!has(name)) return fallback;
    const value = obj[name];
    if (typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max) return value;
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  };
  const steps = intField('steps', 1, 20, DEFAULT_STEPS);
  const failAttempts = intField('failAttempts', 0, 5, DEFAULT_FAIL_ATTEMPTS);

  if (fields.length > 0) return fail();
  return { ok: true, payload: { input, steps, failAttempts }, idempotencyKey };
}

