  send(res, status, { error });
}

function headerValues(rawHeaders: readonly string[], name: string): string[] {
  const values: string[] = [];
  const wanted = name.toLowerCase();
  for (let i = 0; i + 1 < rawHeaders.length; i += 2) {
    if (rawHeaders[i]!.toLowerCase() === wanted) values.push(rawHeaders[i + 1]!);
  }
  return values;
}

/** Reads the whole body as a Buffer, or null if it exceeds the size limit. */
async function readBody(req: IncomingMessage): Promise<Buffer | null> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = chunk as Buffer;
    size += buf.length;
    if (size > MAX_BODY_BYTES) {
      req.resume();
      return null;
    }
    chunks.push(buf);
  }
  return Buffer.concat(chunks);
}

type Route =
  | { kind: 'ui'; methods: string[] }
  | { kind: 'health'; methods: string[] }
  | { kind: 'jobs'; methods: string[] }
  | { kind: 'job'; methods: string[]; id: string };

const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

function classify(path: string): Route | undefined {
  if (path === '/') return { kind: 'ui', methods: ['GET'] };
  if (path === '/health') return { kind: 'health', methods: ['GET'] };
  if (path === '/api/jobs') return { kind: 'jobs', methods: ['GET', 'POST'] };
  const match = JOB_PATH.exec(path);
  if (match) {
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return undefined;
    }
    return { kind: 'job', methods: ['GET'], id };
  }
  return undefined;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const route = classify(url.pathname);
  if (!route) {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }

  const method = req.method === 'HEAD' ? 'GET' : (req.method ?? 'GET');
  if (!route.methods.includes(method)) {
    res.setHeader('allow', route.methods.join(', '));
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
    return;
  }

  switch (route.kind) {
    case 'ui': {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(uiHtml);
      return;
    }

    case 'health': {
      const beat = readHeartbeat(db);
      const up = beat !== undefined && Date.now() - beat <= HEARTBEAT_FRESH_MS;
      send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
      return;
    }

    case 'jobs': {
      if (method === 'GET') {
        send(res, 200, { jobs: listJobs(db).map(toJobView) });
        return;
      }
      await createJob(req, res);
      return;
    }

    case 'job': {
      const row = getJobById(db, route.id);
      if (!row) {
        sendError(res, 404, 'not_found', 'No job with that id.');
        return;
      }
      send(res, 200, toJobView(row));
      return;
    }
  }
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const parsed = parseCreateRequest(
    headerValues(req.rawHeaders, 'content-type'),
    headerValues(req.rawHeaders, 'idempotency-key'),
    body,
  );
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
    return;
  }

  const { payload, idempotencyKey } = parsed;
  const id = randomUUID();
  const now = new Date().toISOString();

  // Check-and-insert happens in one IMMEDIATE transaction; the UNIQUE index on the key backs this up.
  const outcome = transaction(db, () => {
    if (idempotencyKey !== undefined) {
      const existing = getJobByKey(db, idempotencyKey);
      if (existing) {
        return samePayload(existing, payload)
          ? { kind: 'replay' as const, row: existing }
          : { kind: 'conflict' as const };
      }
    }
    insertJob(db, { id, input: payload.input, steps: payload.steps, failAttempts: payload.failAttempts, idempotencyKey: idempotencyKey ?? null, now });
    return { kind: 'created' as const, row: getJobById(db, id)! };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJobView(outcome.row));
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.on('error', (err) => {
  console.error(`server error: ${err.message}`);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log('server shutting down');
  const hard = setTimeout(() => {
    console.error('forcing shutdown');
    process.exit(1);
  }, SHUTDOWN_HARD_MS);
  const grace = setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS);
  server.close(() => {
    clearTimeout(grace);
    clearTimeout(hard);
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

