import { setTimeout as sleep } from 'node:timers/promises';
import {
  claimNextJob, clearHeartbeat, completeJob, failJob, findRunningJob, openDatabase, requeueJob,
  resetAttemptProgress, setProgress, transaction, writeHeartbeat, type JobRow,
} from './db.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

const nowIso = (): string => new Date().toISOString();

function beat(): void {
  try {
    writeHeartbeat(db, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/**
 * Runs one attempt of a job. The attempt is already recorded as `running` with its attempt number.
 * Failure is decided at the first step, before any progress is recorded.
 */
async function processAttempt(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    await sleep(STEP_MS);
    transaction(db, () => {
      if (job.attempts >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure', nowIso());
      else requeueJob(db, job.id, Date.now() + RETRY_DELAY_MS, nowIso());
    });
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    transaction(db, () => {
      if (step < job.steps) setProgress(db, job.id, step, nowIso());
      else completeJob(db, job.id, step, job.input.toUpperCase(), nowIso());
    });
  }
}

async function run(): Promise<void> {
  while (!stopping) {
    try {
      // Between attempts, any row still `running` belongs to an attempt interrupted by a previous
      // worker exit. Replay it from step zero under its recorded attempt number.
      const interrupted = findRunningJob(db);
      if (interrupted) {
        console.log(`resuming interrupted attempt ${interrupted.attempts} of job ${interrupted.id}`);
        transaction(db, () => resetAttemptProgress(db, interrupted.id, nowIso()));
        await processAttempt(interrupted);
        continue;
      }

      const job = claimNextJob(db, Date.now(), nowIso());
      if (!job) {
        await sleep(POLL_MS);
        continue;
      }
      await processAttempt(job);
    } catch (err) {
      console.error('worker error:', err);
      await sleep(POLL_MS);
    }
  }
}

console.log('worker started');
await run();

clearInterval(heartbeatTimer);
try {
  clearHeartbeat(db);
} catch (err) {
  console.error('could not clear heartbeat:', err);
}
db.close();
console.log('worker stopped');

