import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
const APP = process.argv[2];
const PORT = 3950;
const DB = `${process.argv[3]}/nested/dir/jobs.db`;
const base = `http://127.0.0.1:${PORT}`;
const env = { ...process.env, PORT: String(PORT), DATABASE_PATH: DB };
let failures = 0;
const check = (name, cond, extra = '') => { if (!cond) failures++; console.log(`${cond ? 'PASS' : 'FAIL'} ${name} ${cond ? '' : JSON.stringify(extra)}`); };
const start = (script) => spawn('node', ['--disable-warning=ExperimentalWarning', `${APP}/dist/${script}.js`], { env, cwd: APP, stdio: ['ignore', 'pipe', 'pipe'] });
const procs = {};
const post = async (body, headers = {}, raw = false) => {
  const r = await fetch(`${base}/api/jobs`, { method: 'POST', headers: { 'content-type': 'application/json', ...headers }, body: raw ? body : JSON.stringify(body) });
  return { status: r.status, ct: r.headers.get('content-type'), json: await r.json().catch(() => null) };
};
const get = async (p) => { const r = await fetch(base + p); return { status: r.status, ct: r.headers.get('content-type'), json: await r.json().catch(() => null) }; };
const waitFor = async (pred, ms = 15000) => { const t = Date.now(); while (Date.now() - t < ms) { const v = await pred(); if (v) return v; await sleep(50); } return null; };
const jobCount = async () => (await get('/api/jobs')).json.jobs.length;
const finished = (id) => waitFor(async () => { const j = (await get(`/api/jobs/${id}`)).json; return ['completed', 'failed'].includes(j.status) ? j : null; }, 20000);

procs.server = start('server'); procs.worker = start('worker');
const t0 = Date.now();
const up = await waitFor(async () => { try { const h = (await get('/health')).json; return h?.worker === 'up'; } catch { return false; } }, 10000);
check('both start, worker up within 10s', !!up, { elapsed: Date.now() - t0 });

// Job shape & defaults
const a = await post({ input: 'hello' });
check('create 201 queued', a.status === 201 && a.json.status === 'queued' || a.json?.status === 'running', a);
const keys = Object.keys(a.json).sort().join(',');
check('exact public field set', keys === 'attempts,createdAt,error,failAttempts,id,input,progress,result,status,steps,updatedAt', keys);
check('defaults steps 5 failAttempts 0', a.json.steps === 5 && a.json.failAttempts === 0);
check('ISO timestamps', !Number.isNaN(Date.parse(a.json.createdAt)));
const fin = await finished(a.json.id);
check('hello completes as HELLO', fin?.status === 'completed' && fin.result.output === 'HELLO' && fin.progress.completed === 5 && fin.attempts === 1 && fin.error === null, fin);

// Validation matrix
const bad = [
  [{}, 'input'], [{ input: '' }, 'input'], [{ input: '   ' }, 'input'], [{ input: 'x'.repeat(1001) }, 'input'],
  [{ input: 5 }, 'input'], [{ input: null }, 'input'], [{ input: 'a', steps: '3' }, 'steps'], [{ input: 'a', steps: 0 }, 'steps'],
  [{ input: 'a', steps: 21 }, 'steps'], [{ input: 'a', steps: 2.5 }, 'steps'], [{ input: 'a', steps: null }, 'steps'],
  [{ input: 'a', failAttempts: 6 }, 'failAttempts'], [{ input: 'a', failAttempts: -1 }, 'failAttempts'], [{ input: 'a', failAttempts: true }, 'failAttempts'],
  [{ input: 'a', extra: 1 }, 'extra'], [{ input: 'a', __proto__x: 1 }, '__proto__x'], [[], 'body'], [null, 'body'], ['str', 'body'], [42, 'body'],
];
const before = await jobCount();
for (const [body, field] of bad) {
  const r = await post(body);
  const ok = r.status === 400 && r.json.error.code === 'invalid_request' && r.json.error.fields.some((f) => f.field === field) && r.ct.startsWith('application/json');
  check(`reject ${JSON.stringify(body).slice(0, 40)} -> ${field}`, ok, r.json);
}
// Multiple errors at once
const multi = await post({ input: '', steps: '3', bogus: 1 });
check('collects all field errors', multi.json?.error?.fields?.map((f) => f.field).sort().join(',') === 'bogus,input,steps', multi.json);
// malformed json / content types / idempotency key
const mj = await post('{"input":', {}, true);
check('malformed JSON -> body', mj.status === 400 && mj.json.error.fields[0].field === 'body', mj.json);
const noct = await fetch(`${base}/api/jobs`, { method: 'POST', body: '{"input":"a"}' });
check('missing content-type -> 400 body', noct.status === 400 && (await noct.json()).error.fields[0].field === 'body');
const txt = await post('{"input":"a"}', { 'content-type': 'text/plain' }, true);
check('text/plain -> 400 body', txt.status === 400);
const ctOk = await post('{"input":"charset-ok"}', { 'content-type': 'Application/JSON; charset=utf-8' }, true);
check('content-type case/params accepted', ctOk.status === 201, ctOk.json);
const badKey = await post({ input: 'a' }, { 'idempotency-key': 'bad key!' });
check('bad Idempotency-Key -> field', badKey.status === 400 && badKey.json.error.fields[0].field === 'Idempotency-Key', badKey.json);
const longKey = await post({ input: 'a' }, { 'idempotency-key': 'k'.repeat(129) });
check('129-char key rejected', longKey.status === 400);
const after = await jobCount();
check('invalid requests created no jobs', after === before + 1, { before, after }); // +1 for charset-ok

// Unicode length boundary
const emoji = '😀'.repeat(500); // length 1000
const uOk = await post({ input: emoji });
check('1000 UTF-16 units accepted', uOk.status === 201);
const uBad = await post({ input: emoji + 'a' });
check('1001 UTF-16 units rejected', uBad.status === 400);
check('input stored exactly', uOk.json.input === emoji);

// Routing
for (const [p, s, c] of [['/nope', 404, 'not_found'], ['/api/jobs/does-not-exist', 404, 'not_found'], ['/api/jobs/x%ZZ', 404, 'not_found'], ['/api/jobs?x=1', 200, undefined], ['/health?y=2', 200, undefined]]) {
  const r = await get(p);
  check(`GET ${p} -> ${s}`, r.status === s && (!c || r.json.error.code === c), r.json);
  check(`  ${p} JSON content-type`, r.ct?.startsWith('application/json') || p === '/api/jobs/x%ZZ' || p.startsWith('/nope') === false);
}
for (const [p, m] of [['/health', 'POST'], ['/api/jobs', 'PUT'], [`/api/jobs/${a.json.id}`, 'DELETE'], ['/', 'POST']]) {
  const r = await fetch(base + p, { method: m, headers: { 'content-type': 'application/json' }, body: m === 'POST' || m === 'PUT' ? '{}' : undefined });
  const j = await r.json().catch(() => null);
  check(`${m} ${p} -> 405`, r.status === 405 && j?.error?.code === 'method_not_allowed', j);
}

// Idempotency
const k1 = await post({ input: 'idem' }, { 'idempotency-key': 'key-1' });
const k2 = await post({ input: 'idem', steps: 5, failAttempts: 0 }, { 'idempotency-key': 'key-1' });
check('idem first 201, replay 200 same id', k1.status === 201 && k2.status === 200 && k1.json.id === k2.json.id, [k1.status, k2.status]);
const k3 = await post({ input: 'idem', steps: 6 }, { 'idempotency-key': 'key-1' });
check('idem different payload 409', k3.status === 409 && k3.json.error.code === 'idempotency_conflict');
const sim = await Promise.all([1, 2, 3, 4, 5].map(() => post({ input: 'race' }, { 'idempotency-key': 'race-key' })));
const raceIds = new Set(sim.map((r) => r.json.id));
check('simultaneous same key -> one job', raceIds.size === 1, sim.map((r) => r.status));
const nk1 = await post({ input: 'nokey' }); const nk2 = await post({ input: 'nokey' });
check('no key -> distinct jobs', nk1.json.id !== nk2.json.id);

// Retries
const rr = {};
for (const f of [0, 1, 2, 3, 5]) rr[f] = await post({ input: `retry${f}`, steps: 2, failAttempts: f });
const res = {};
for (const f of [0, 1, 2, 3, 5]) res[f] = await finished(rr[f].json.id);
check('failAttempts 0 -> completed attempts 1', res[0].status === 'completed' && res[0].attempts === 1, res[0]);
check('failAttempts 1 -> completed attempts 2', res[1].status === 'completed' && res[1].attempts === 2, res[1]);
check('failAttempts 2 -> completed attempts 3', res[2].status === 'completed' && res[2].attempts === 3 && res[2].result.output === 'RETRY2', res[2]);
for (const f of [3, 5]) check(`failAttempts ${f} -> failed attempts 3`, res[f].status === 'failed' && res[f].attempts === 3 && res[f].error === 'transient failure' && res[f].result === null && res[f].progress.completed === 0, res[f]);

// Processing timing & progress on a 20-step job
const big = await post({ input: 'long-job', steps: 20 });
const seen = new Set(); let runningSeen = false; const t1 = Date.now();
const doneBig = await waitFor(async () => { const j = (await get(`/api/jobs/${big.json.id}`)).json; if (j.status === 'running') runningSeen = true; seen.add(j.progress.completed); return j.status === 'completed' ? j : null; }, 20000);
const elapsed = Date.now() - t1;
check('20-step job completes with intermediate progress', doneBig && runningSeen && seen.size > 5, { elapsed, seen: [...seen] });
check('20-step takes ~2s', elapsed >= 1800 && elapsed <= 4000, elapsed);
check('20-step output', doneBig?.result?.output === 'LONG-JOB');

// FIFO: queue three jobs with the worker busy
const f1 = await post({ input: 'f1', steps: 3 }); const f2 = await post({ input: 'f2', steps: 3 }); const f3 = await post({ input: 'f3', steps: 3 });
const fifoDone = await finished(f3.json.id);
const ts = [f1, f2, f3].map((x) => x.json.id);
const all = (await get('/api/jobs')).json.jobs;
const order = all.map((j) => j.id);
check('list newest first', order.indexOf(f3.json.id) < order.indexOf(f1.json.id));
const j1 = await finished(f1.json.id), j2 = await finished(f2.json.id);
check('FIFO order f1 <= f2 <= f3 completion', j1.updatedAt <= j2.updatedAt && j2.updatedAt <= fifoDone.updatedAt);

// Pickup latency
const pl = await post({ input: 'pickup', steps: 1 });
const plStart = Date.now();
const plRunning = await waitFor(async () => (await get(`/api/jobs/${pl.json.id}`)).json.status !== 'queued', 3000);
check('pickup within 1s', !!plRunning && Date.now() - plStart < 1000, Date.now() - plStart);

// Heartbeat: kill worker, expect down within 3s
procs.worker.kill('SIGKILL');
const downAt = Date.now();
const down = await waitFor(async () => (await get('/health')).json.worker === 'down', 6000);
check('worker down within 3s of SIGKILL', !!down && Date.now() - downAt <= 3000, Date.now() - downAt);

// Durability: a job submitted while the worker is dead, then recovery mid-attempt
const dur = await post({ input: 'durable', steps: 10, failAttempts: 1 });
const durRec = dur.json.id;
procs.worker = start('worker');
const upAgain = await waitFor(async () => (await get('/health')).json.worker === 'up', 10000);
check('worker up again after restart', !!upAgain);
const durFin = await finished(durRec);
check('queued job survives worker death and completes', durFin?.status === 'completed' && durFin.attempts === 2 && durFin.result.output === 'DURABLE', durFin);

// Kill worker mid-attempt
const mid = await post({ input: 'midkill', steps: 20 });
await waitFor(async () => (await get(`/api/jobs/${mid.json.id}`)).json.progress.completed >= 3, 5000);
procs.worker.kill('SIGKILL');
const before2 = (await get(`/api/jobs/${mid.json.id}`)).json;
check('killed mid-attempt leaves running', before2.status === 'running', before2);
procs.worker = start('worker');
const midFin = await finished(mid.json.id);
check('recovered mid-attempt job completes exactly once', midFin?.status === 'completed' && midFin.attempts === 1 && midFin.result.output === 'MIDKILL' && midFin.progress.completed === 20, midFin);

// Kill during retry delay / attempt 3
const att3 = await post({ input: 'att3', steps: 4, failAttempts: 5 });
await waitFor(async () => (await get(`/api/jobs/${att3.json.id}`)).json.attempts === 3, 5000);
procs.worker.kill('SIGKILL');
procs.worker = start('worker');
const att3Fin = await finished(att3.json.id);
check('interrupted during attempt 3 -> failed with attempts 3 (no extra retry)', att3Fin?.status === 'failed' && att3Fin.attempts === 3, att3Fin);

// Restart server abruptly and check persistence + idempotency across restart
procs.server.kill('SIGKILL');
await sleep(300);
